\textbf{Hamming distance}
\begin{itemize}
    \item Used for bit/binary vectors: counts number of bits that differ
    \item Can be used more generally for discrete data, to count matches
\end{itemize}

\textbf{Matching coefficient}
\begin{itemize}
    \item Hamming distance normalized by number of attributes/bits
\end{itemize}

